[ApiController]
[Authorize]
[RequireModule("social")]
public abstract class SocialApiControllerBase : ControllerBase
{
    protected ActionResult<ApiResponse<T>> FromResult<T>(Result<T> r)=>r.IsFailure?BadRequest(ApiResponse<T>.Fail(r.Error??"Falha.")):Ok(ApiResponse<T>.Ok(r.Value!));
    protected ActionResult<ApiResponse<object>> FromResult(Result r)=>r.IsFailure?BadRequest(ApiResponse<object>.Fail(r.Error??"Falha.")):Ok(ApiResponse<object>.Ok(new{}));
}
