[Route("api/social/export")] public sealed class SocialExportacaoController:SocialApiControllerBase{private readonly ISocialExportacaoService _s; public SocialExportacaoController(ISocialExportacaoService s)=>_s=s; [HttpGet("{recurso}.{formato}")] public async Task<IActionResult> Exportar(string recurso,string formato,CancellationToken ct){var r=await _s.ExportarAsync(recurso,formato,ct); if(r.IsFailure)return BadRequest(ApiResponse<object>.Fail(r.Error??"Falha.")); return File(r.Value??Array.Empty<byte>(),formato.Equals("json",StringComparison.OrdinalIgnoreCase)?"application/json":"text/csv",$"{recurso}.{formato}");}}
